#include <vector>
#include <string>
#include <unordered_map>

using namespace std;

class Solution {
public:
    vector<int> findNumOfValidWords(vector<string>& words, vector<string>& puzzles) {
        unordered_map<int, int> freq;
        for (auto& word : words) {
            int mask = 0;
            for (char c : word)
                mask |= 1 << (c - 'a');
            if (__builtin_popcount(mask) <= 7)
                freq[mask]++;
        }

        vector<int> res;
        for (auto& p : puzzles) {
            int total = 0;
            int mask = 0;
            for (int i = 0; i < 7; ++i)
                mask |= 1 << (p[i] - 'a');

            int sub = mask;
            int first = 1 << (p[0] - 'a');
            while (sub) {
                if (sub & first)
                    total += freq[sub];
                sub = (sub - 1) & mask;
            }
            res.push_back(total);
        }
        return res;
    }
};
